+// Número de factura SSS-AAAA-NNNNNN (brain de empresa: estandares/documentos-fiscales.md).
+// Un valor fuera de rango es un error: nunca se trunca ni se ajusta.
+export function numeroFactura(sucursal, gestion, correlativo) {
+  const entero = (v, min, max, nombre) => {
+    if (!Number.isInteger(v) || v < min || v > max) throw new RangeError(`${nombre} fuera de rango (${min}-${max})`);
+    return v;
+  };
+  const sss = String(entero(sucursal, 1, 999, "Sucursal")).padStart(3, "0");
+  const aaaa = String(entero(gestion, 1000, 9999, "Gestión"));
+  const nnnnnn = String(entero(correlativo, 1, 999999, "Correlativo")).padStart(6, "0");
+  return `${sss}-${aaaa}-${nnnnnn}`;
+}
